local TattooArtist = {}
local PRODUCTS = {
    simple_tattoo = { name = "Preprosta tetovaža", inkCost = 1, needleCost = 1, time = 2, cost = 20, artistry = 40, happiness = 2, description = "Preprosta tetovaža za vojake." },
    tribal_tattoo = { name = "Plemenska tetovaža", inkCost = 2, needleCost = 1, time = 4, cost = 50, artistry = 55, prestige = 2, happiness = 3, description = "Plemenska tetovaža z vzorci." },
    heraldic_tattoo = { name = "Heraldična tetovaža", inkCost = 2, needleCost = 1, silverCost = 1, time = 6, cost = 120, artistry = 70, prestige = 5, happiness = 4, description = "Heraldična tetovaža z grbom." },
    silver_ink_tattoo = { name = "Srebrnočrnilna tetovaža", inkCost = 2, silverCost = 1, goldCost = 1, needleCost = 1, time = 9, cost = 280, artistry = 82, prestige = 10, happiness = 5, description = "Tetovaža s srebrnim črnilom za plemiče." },
    gold_ink_tattoo = { name = "Zlatočrnilna tetovaža", inkCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, needleCost = 1, time = 12, cost = 600, artistry = 92, prestige = 18, happiness = 7, description = "Tetovaža z zlatim črnilom za visoke plemiče." },
    royal_grand_tattoo = { name = "Kraljevski veliki tetovaža", inkCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, needleCost = 1, time = 17, cost = 1500, artistry = 100, prestige = 38, happiness = 12, description = "Velika kraljevska tetovaža z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Tetovažna postaja", cost = { gold = 250, wood = 120, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    tattoo_parlor = { name = "Tetovažnica", cost = { gold = 850, wood = 250, stone = 400, ink = 8 }, upkeep = 21, qualityBonus = 18 },
    artistry_room = { name = "Umetniška soba", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, needle = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_tattoo_atelier = { name = "Kraljevski atelje tetovaž", cost = { gold = 8800, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 175, qualityBonus = 55, prestigeBonus = 40 },
}
TattooArtist.inkStock = 18; TattooArtist.needleStock = 14; TattooArtist.silverStock = 8; TattooArtist.goldStock = 6; TattooArtist.jewelStock = 6; TattooArtist.pearlStock = 4
TattooArtist.productStock = {}; TattooArtist.buildings = {}; TattooArtist.maker = nil; TattooArtist.activeMaking = {}; TattooArtist.totalProducts = 0; TattooArtist.dayTimer = 0
function TattooArtist.init() TattooArtist.inkStock=18; TattooArtist.needleStock=14; TattooArtist.silverStock=8; TattooArtist.goldStock=6; TattooArtist.jewelStock=6; TattooArtist.pearlStock=4; TattooArtist.productStock={}; TattooArtist.buildings={}; TattooArtist.maker=nil; TattooArtist.activeMaking={}; TattooArtist.totalProducts=0; TattooArtist.dayTimer=0; print("[TattooArtist] Royal Tattoo Artist System initialized (6 products, 4 buildings)") end
function TattooArtist.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TattooArtist.maker={name=n or ("Tetovažar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tetovažar najet: %s (spretnost: %d)",TattooArtist.maker.name,s),"success") end; return true end
function TattooArtist.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TattooArtist.build(id) local ok,e=TattooArtist.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TattooArtist.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TattooArtist.getQualityBonus() local b=0; for _,bd in ipairs(TattooArtist.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TattooArtist.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.inkCost and TattooArtist.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.needleCost and TattooArtist.needleStock<(d.needleCost or 0) then return false,"Premalo igel" end; if d.silverCost and TattooArtist.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TattooArtist.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TattooArtist.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TattooArtist.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TattooArtist.buildings==0 then return false,"Potrebna delavnica" end; if not TattooArtist.maker then return false,"Potreben tetovažar" end; return true end
function TattooArtist.make(pt,qty) qty=qty or 1; local ok,e=TattooArtist.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.inkCost then TattooArtist.inkStock=TattooArtist.inkStock-d.inkCost*qty end; if d.needleCost then TattooArtist.needleStock=TattooArtist.needleStock-d.needleCost*qty end; if d.silverCost then TattooArtist.silverStock=TattooArtist.silverStock-d.silverCost*qty end; if d.goldCost then TattooArtist.goldStock=TattooArtist.goldStock-d.goldCost*qty end; if d.jewelCost then TattooArtist.jewelStock=TattooArtist.jewelStock-d.jewelCost*qty end; if d.pearlCost then TattooArtist.pearlStock=TattooArtist.pearlStock-d.pearlCost*qty end; local t=d.time; if TattooArtist.maker then t=math.max(1,t-math.floor(TattooArtist.maker.skill/12)) end; table.insert(TattooArtist.activeMaking,{id="tattoo_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TattooArtist.completeMaking(m) local q=1.0+(TattooArtist.getQualityBonus()/100); if TattooArtist.maker then q=q+(TattooArtist.maker.skill/180) end; q=math.min(2.0,q); TattooArtist.productStock[m.productType]=(TattooArtist.productStock[m.productType] or 0)+m.quantity; TattooArtist.totalProducts=TattooArtist.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TattooArtist.maker then TattooArtist.maker.itemsMade=TattooArtist.maker.itemsMade+m.quantity; if math.random()<0.20 then TattooArtist.maker.skill=math.min(100,TattooArtist.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tetovaža izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tattoo.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function TattooArtist.update(dt) if not _G.state then return end; TattooArtist.dayTimer=TattooArtist.dayTimer+dt; if TattooArtist.dayTimer>=30 then TattooArtist.dayTimer=0; for i=#TattooArtist.activeMaking,1,-1 do local m=TattooArtist.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TattooArtist.completeMaking(m); table.remove(TattooArtist.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TattooArtist.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TattooArtist.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TattooArtist.getStats() return {inkStock=TattooArtist.inkStock,needleStock=TattooArtist.needleStock,silverStock=TattooArtist.silverStock,goldStock=TattooArtist.goldStock,jewelStock=TattooArtist.jewelStock,pearlStock=TattooArtist.pearlStock,productStock=TattooArtist.productStock,numBuildings=#TattooArtist.buildings,hasMaker=TattooArtist.maker~=nil,makerName=TattooArtist.maker and TattooArtist.maker.name or "—",makerSkill=TattooArtist.maker and TattooArtist.maker.skill or 0,activeMaking=#TattooArtist.activeMaking,totalProducts=TattooArtist.totalProducts} end
return TattooArtist
